private String reconfBlockReportInterval(String property, String newVal)
    throws ReconfigurationException {
  long newIntervalMs;
  if (newVal == null) {
    newIntervalMs = DFS_BLOCKREPORT_INTERVAL_MSEC_DEFAULT;
  } else {
    try {
      newIntervalMs = Long.parseLong(newVal);
    } catch (NumberFormatException nfe) {
      throw new ReconfigurationException(property, newVal, getConf().get(
          property), nfe);
    }
  }
  if (newIntervalMs <= 0) {
    throw new ReconfigurationException(property, newVal, getConf().get(
        property),
        new IllegalArgumentException(
            "Block report interval must be a positive value: "
                + newIntervalMs));
  }
  LOG.info("Reconfiguring {} to {}", property, newIntervalMs);
  for (BPOfferService bpos : getAllBpOs()) {
    bpos.setBlockReportIntervalMs(newIntervalMs);
  }
  return Long.toString(newIntervalMs);
}

