30	/**
31	 * The BlockReportLeaseManager manages block report leases.<p/>
32	 *
33	 * DataNodes request BR leases from the NameNode by sending a heartbeat with
34	 * the requestBlockReportLease field set.  The NameNode may choose to respond
35	 * with a non-zero lease ID.  If so, that DataNode can send a block report with
36	 * the given lease ID for the next few minutes.  The NameNode will accept
37	 * these full block reports.<p/>
38	 *
39	 * BR leases limit the number of incoming full block reports to the NameNode
40	 * at any given time.  For compatibility reasons, the NN will always accept
41	 * block reports sent with a lease ID of 0 and queue them for processing
42	 * immediately.  Full block reports which were manually triggered will also
43	 * have a lease ID of 0, bypassing the rate-limiting.<p/>
44	 *
45	 * Block report leases expire after a certain amount of time.  This mechanism
46	 * is in place so that a DN which dies while holding a lease does not
47	 * permanently decrease the number of concurrent block reports which the NN is
48	 * willing to accept.<p/>
49	 *
50	 * When considering which DNs to grant a BR lease, the NameNode gives priority
51	 * to the DNs which have gone the longest without sending a full block
52	 * report.<p/>
53	 */
54	class BlockReportLeaseManager {
55	  static final Logger LOG =
56	      LoggerFactory.getLogger(BlockReportLeaseManager.class);
57	
58	  private static class NodeData {
59	    /**
60	     * The UUID of the datanode.
61	     */
62	    final String datanodeUuid;
63	
64	    /**
65	     * The lease ID, or 0 if there is no lease.
66	     */
67	    long leaseId;
68	
69	    /**
70	     * The time when the lease was issued, or 0 if there is no lease.
71	     */
72	    long leaseTimeMs;
73	
74	    /**
75	     * Previous element in the list.
76	     */
77	    NodeData prev;
78	
79	    /**
80	     * Next element in the list.
81	     */
82	    NodeData next;
83	
84	    static NodeData ListHead(String name) {
85	      NodeData node = new NodeData(name);
86	      node.next = node;
87	      node.prev = node;
88	      return node;
89	    }
90	
91	    NodeData(String datanodeUuid) {
92	      this.datanodeUuid = datanodeUuid;
93	    }
94	
95	    void removeSelf() {
96	      if (this.prev != null) {
97	        this.prev.next = this.next;
98	      }
99	      if (this.next != null) {
100	        this.next.prev = this.prev;
101	      }
102	      this.next = null;
103	      this.prev = null;
104	    }
105	
106	    void addToEnd(NodeData node) {
107	      Preconditions.checkState(node.next == null);
108	      Preconditions.checkState(node.prev == null);
109	      node.prev = this.prev;
110	      node.next = this;
111	      this.prev.next = node;
112	      this.prev = node;
113	    }
114	
115	    void addToBeginning(NodeData node) {
116	      Preconditions.checkState(node.next == null);
117	      Preconditions.checkState(node.prev == null);
118	      node.next = this.next;
119	      node.prev = this;
120	      this.next.prev = node;
121	      this.next = node;
122	    }
123	  }
124	
125	  /**
126	   * List of datanodes which don't currently have block report leases.
127	   */
128	  private final NodeData deferredHead = NodeData.ListHead("deferredHead");
129	
130	  /**
131	   * List of datanodes which currently have block report leases.
132	   */
133	  private final NodeData pendingHead = NodeData.ListHead("pendingHead");
134	
135	  /**
136	   * Maps datanode UUIDs to NodeData.
137	   */
138	  private final HashMap<String, NodeData> nodes = new HashMap<>();
139	
140	  /**
141	   * The current length of the pending list.
142	   */
143	  private int numPending = 0;
144	
145	  /**
146	   * The maximum number of leases to hand out at any given time.
147	   */
148	  private final int maxPending;
149	
150	  /**
151	   * The number of milliseconds after which a lease will expire.
152	   */
153	  private final long leaseExpiryMs;
154	
155	  /**
156	   * The next ID we will use for a block report lease.
157	   */
158	  private long nextId = ThreadLocalRandom.current().nextLong();
159	
160	  BlockReportLeaseManager(Configuration conf) {
161	    this(conf.getInt(
162	          DFSConfigKeys.DFS_NAMENODE_MAX_FULL_BLOCK_REPORT_LEASES,
163	          DFSConfigKeys.DFS_NAMENODE_MAX_FULL_BLOCK_REPORT_LEASES_DEFAULT),
164	        conf.getLong(
165	          DFSConfigKeys.DFS_NAMENODE_FULL_BLOCK_REPORT_LEASE_LENGTH_MS,
166	          DFSConfigKeys.DFS_NAMENODE_FULL_BLOCK_REPORT_LEASE_LENGTH_MS_DEFAULT));
167	  }
168	
169	  BlockReportLeaseManager(int maxPending, long leaseExpiryMs) {
170	    Preconditions.checkArgument(maxPending >= 1,
171	        "Cannot set the maximum number of block report leases to a " +
172	            "value less than 1.");
173	    this.maxPending = maxPending;
174	    Preconditions.checkArgument(leaseExpiryMs >= 1,
175	        "Cannot set full block report lease expiry period to a value " +
176	         "less than 1.");
177	    this.leaseExpiryMs = leaseExpiryMs;
178	  }
179	
180	  /**
181	   * Get the next block report lease ID.  Any number is valid except 0.
182	   */
183	  private long getNextId() {
184	    return ++nextId == 0L ? ++nextId : nextId;
185	  }
186	
187	  public synchronized void register(DatanodeDescriptor dn) {
188	    registerNode(dn);
189	  }
190	
191	  private synchronized NodeData registerNode(DatanodeDescriptor dn) {
192	    if (nodes.containsKey(dn.getDatanodeUuid())) {
193	      LOG.info("Can't register DN {} because it is already registered.",
194	          dn.getDatanodeUuid());
195	      return null;
196	    }
197	    NodeData node = new NodeData(dn.getDatanodeUuid());
198	    deferredHead.addToBeginning(node);
199	    nodes.put(dn.getDatanodeUuid(), node);
200	    LOG.info("Registered DN {} ({}).", dn.getDatanodeUuid(), dn.getXferAddr());
201	    return node;
202	  }
203	
204	  private synchronized void remove(NodeData node) {
205	    if (node.leaseId != 0) {
206	      numPending--;
207	      node.leaseId = 0;
208	      node.leaseTimeMs = 0;
209	    }
210	    node.removeSelf();
211	  }
212	
213	  public synchronized void unregister(DatanodeDescriptor dn) {
214	    NodeData node = nodes.remove(dn.getDatanodeUuid());
215	    if (node == null) {
216	      LOG.info("Can't unregister DN {} because it is not currently " +
217	          "registered.", dn.getDatanodeUuid());
218	      return;
219	    }
220	    remove(node);
221	  }
222	
223	  public synchronized long requestLease(DatanodeDescriptor dn) {
224	    NodeData node = nodes.get(dn.getDatanodeUuid());
225	    if (node == null) {
226	      LOG.warn("DN {} ({}) requested a lease even though it wasn't yet " +
227	          "registered.  Registering now.", dn.getDatanodeUuid(),
228	          dn.getXferAddr());
229	      node = registerNode(dn);
230	    }
231	    if (node.leaseId != 0) {
232	      // The DataNode wants a new lease, even though it already has one.
233	      // This can happen if the DataNode is restarted in between requesting
234	      // a lease and using it.
235	      LOG.debug("Removing existing BR lease 0x{} for DN {} in order to " +
236	               "issue a new one.", Long.toHexString(node.leaseId),
237	               dn.getDatanodeUuid());
238	    }
239	    remove(node);
240	    long monotonicNowMs = Time.monotonicNow();
241	    pruneExpiredPending(monotonicNowMs);
242	    if (numPending >= maxPending) {
243	      if (LOG.isDebugEnabled()) {
244	        StringBuilder allLeases = new StringBuilder();
245	        String prefix = "";
246	        for (NodeData cur = pendingHead.next; cur != pendingHead;
247	             cur = cur.next) {
248	          allLeases.append(prefix).append(cur.datanodeUuid);
249	          prefix = ", ";
250	        }
251	        LOG.debug("Can't create a new BR lease for DN {}, because " +
252	              "numPending equals maxPending at {}.  Current leases: {}",
253	              dn.getDatanodeUuid(), numPending, allLeases.toString());
254	      }
255	      return 0;
256	    }
257	    numPending++;
258	    node.leaseId = getNextId();
259	    node.leaseTimeMs = monotonicNowMs;
260	    pendingHead.addToEnd(node);
261	    if (LOG.isDebugEnabled()) {
262	      LOG.debug("Created a new BR lease 0x{} for DN {}.  numPending = {}",
263	          Long.toHexString(node.leaseId), dn.getDatanodeUuid(), numPending);
264	    }
265	    return node.leaseId;
266	  }
267	
268	  private synchronized boolean pruneIfExpired(long monotonicNowMs,
269	                                              NodeData node) {
270	    if (monotonicNowMs < node.leaseTimeMs + leaseExpiryMs) {
271	      return false;
272	    }
273	    LOG.info("Removing expired block report lease 0x{} for DN {}.",
274	        Long.toHexString(node.leaseId), node.datanodeUuid);
275	    Preconditions.checkState(node.leaseId != 0);
276	    remove(node);
277	    deferredHead.addToBeginning(node);
278	    return true;
279	  }
280	
281	  private synchronized void pruneExpiredPending(long monotonicNowMs) {
282	    NodeData cur = pendingHead.next;
283	    while (cur != pendingHead) {
284	      NodeData next = cur.next;
285	      if (!pruneIfExpired(monotonicNowMs, cur)) {
286	        return;
287	      }
288	      cur = next;
289	    }
290	    LOG.trace("No entries remaining in the pending list.");
291	  }
292	
293	  public synchronized boolean checkLease(DatanodeDescriptor dn,
294	                                         long monotonicNowMs, long id) {
295	    if (id == 0) {
296	      LOG.debug("Datanode {} is using BR lease id 0x0 to bypass " +
297	          "rate-limiting.", dn.getDatanodeUuid());
298	      return true;
299	    }
300	    NodeData node = nodes.get(dn.getDatanodeUuid());
301	    if (node == null) {
302	      LOG.info("BR lease 0x{} is not valid for unknown datanode {}",
303	          Long.toHexString(id), dn.getDatanodeUuid());
304	      return false;
305	    }
306	    if (node.leaseId == 0) {
307	      LOG.warn("BR lease 0x{} is not valid for DN {}, because the DN " +
308	               "is not in the pending set.",
309	               Long.toHexString(id), dn.getDatanodeUuid());
310	      return false;
311	    }
312	    if (pruneIfExpired(monotonicNowMs, node)) {
313	      LOG.warn("BR lease 0x{} is not valid for DN {}, because the lease " +
314	               "has expired.", Long.toHexString(id), dn.getDatanodeUuid());
315	      return false;
316	    }
317	    if (id != node.leaseId) {
318	      LOG.warn("BR lease 0x{} is not valid for DN {}.  Expected BR lease 0x{}.",
319	          Long.toHexString(id), dn.getDatanodeUuid(),
320	          Long.toHexString(node.leaseId));
321	      return false;
322	    }
323	    if (LOG.isTraceEnabled()) {
324	      LOG.trace("BR lease 0x{} is valid for DN {}.",
325	          Long.toHexString(id), dn.getDatanodeUuid());
326	    }
327	    return true;
328	  }
329	
330	  public synchronized long removeLease(DatanodeDescriptor dn) {
331	    NodeData node = nodes.get(dn.getDatanodeUuid());
332	    if (node == null) {
333	      LOG.info("Can't remove lease for unknown datanode {}",
334	               dn.getDatanodeUuid());
335	      return 0;
336	    }
337	    long id = node.leaseId;
338	    if (id == 0) {
339	      LOG.debug("DN {} has no lease to remove.", dn.getDatanodeUuid());
340	      return 0;
341	    }
342	    remove(node);
343	    deferredHead.addToEnd(node);
344	    if (LOG.isTraceEnabled()) {
345	      LOG.trace("Removed BR lease 0x{} for DN {}.  numPending = {}",
346	                Long.toHexString(id), dn.getDatanodeUuid(), numPending);
347	    }
348	    return id;
349	  }
